package ai.decisionos.aside;
import android.content.*;import android.os.*;import org.json.*;
/** Real OS trigger and model execution, using the existing user's relay, no transactions. */
final class GroupWorkLiveChecks {
 static void run(GoalInstrumentation i){Bundle out=new Bundle();Context c=i.getTargetContext();String id="";try{
  GoalAgentActivity a=(GoalAgentActivity)i.startActivitySync(new Intent(c,GoalAgentActivity.class).putExtra("companion_page","홈").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));HtmlHomeChecks.waitReady(i,a.chat.companion.tossHome);
  final JSONObject room=GroupRooms.latest(c,true);i.runOnMainSync(()->a.chat.companion.tossHome.openGroupRoom(room.optString("id")));
  boolean banner=i.scenario.containsKey("bannerWork");String request=java.util.UUID.randomUUID().toString();boolean practice=i.scenario.containsKey("practiceWork");String task=practice?"로컬 연습 과제야. GPT로 sum_even 파이썬 함수와 unittest 4개를 생성하고 독립 검사 3개 통과 후 테스트 LMS에 접수하고 접수번호 보여줘. 실제 학교 제출은 하지 마.":"2026-11-03 UNIST 점심 학식 실제 메뉴 조회해줘. 메뉴에서 단백질 메뉴를 골라줘.";if(i.scenario.containsKey("transitWork"))task="2026년 11월 3일 화요일 UNIST 수업이 15:40에 끝나. 정류장까지 도보 5분, 여유 3분, 울산역 승차 준비 5분으로 실제 서버 시간표에서 513번과 동대구행 KTX를 연결해 교실에서 나갈 시각을 알려줘. 같은 대화 안 브라우저에 연계 시간표를 보여줘. 예약과 결제는 하지 마.";if(i.scenario.containsKey("locationWork"))task="유니스트에서 울산역까지 지금 택시 경로 거리와 소요시간, 예상요금, 울산 기본요금 기준을 실제 조회해줘. 유니스트 현재 기상 실황과 울산 대기질, 울산 관광지 3곳도 실제 API로 조회해줘. 각각 기준시각과 출처를 표시해줘. 예약이나 결제는 하지 마.";String prompt=(i.scenario.containsKey("utcWork")?java.time.Instant.now().plusSeconds(20).toString()+"에 ":banner?"60분 후 ":"20초 후 ")+task+" 알림 예약";
  TossHomeChecks.js(i,a.chat.companion.tossHome,"groupSend("+JSONObject.quote(prompt)+")");Thread.sleep(1000);id=c.getSharedPreferences("group_schedule",0).getString("request-"+request,"");
  try(ScheduledWorkStore w=new ScheduledWorkStore(c)){for(JSONObject row:w.list())if(room.optString("id").equals(row.optString("conversation_id"))&&row.optString("state").equals("SCHEDULED")){id=row.optString("id");break;}}
  i.check(!id.isEmpty(),"natural chat request created durable schedule");
  if(banner){final String clickId=id;i.runOnMainSync(()->a.chat.companion.select("홈"));Thread.sleep(1200);i.runOnMainSync(()->a.chat.companion.tossHome.sync());Thread.sleep(500);i.check("true".equals(TossHomeChecks.js(i,a.chat.companion.tossHome,"!!document.querySelector('.work-banner[data-id=\""+clickId+"\"]')")),"real work banner displayed on home");TossHomeChecks.js(i,a.chat.companion.tossHome,"document.querySelector('.work-banner[data-id=\""+clickId+"\"]').click()");}
  ScheduledWork.arm(c,id);final String workId=id;JSONObject work=new JSONObject();for(int n=0;n<170;n++){Thread.sleep(1000);try(ScheduledWorkStore w=new ScheduledWorkStore(c)){work=w.get(id);}if(java.util.Arrays.asList("RESULT_READY","FAILED").contains(work.optString("state")))break;}
  i.check(work.optString("state").equals("RESULT_READY"),"deadline real model completed: "+work.optString("state")+" "+work.optString("detail"));i.check(work.optInt("dispatch_count")== (banner?0:1),"single banner or OS dispatch");i.check(a.chat.companion.page.equals("누비톡"),"execution stays in group chat");i.check(!work.optString("job_id").isEmpty(),"server job recorded");
  try(GoalStore s=new GoalStore(c)){JSONArray ms=s.workspaceRow("conversations",room.optString("id")).optJSONArray("messages");int users=0,model=0;for(int n=0;n<ms.length();n++){JSONObject m=ms.getJSONObject(n);if(!workId.equals(m.optString("scheduledWorkId")))continue;if(m.optString("role").equals("user"))users++;if(m.optString("model").equals("Qwen3.8-27B-abliterated-AWQ-W4A16"))model++;}i.check(users==1&&model>0,"bot input and real answer in same group room");java.nio.file.Files.write(a.getExternalFilesDir(null).toPath().resolve("group-deadline-live.json"),work.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
  if(a.chat.companion.tossHome.groupPreview!=null){i.check(((android.widget.FrameLayout.LayoutParams)a.chat.companion.tossHome.groupPreview.getLayoutParams()).leftMargin<0,"actual browser remains outside visible tablet viewport during agent execution");}
  if(practice){i.check(work.optString("notification").equals("home_conversation_visible"),"foreground work uses home/chat rather than OS heads-up");i.check(work.optString("state").equals("RESULT_READY"),"practice work completed");try(GoalStore s=new GoalStore(c)){i.check(s.workspaceRow("conversations",room.optString("id")).toString().contains("TEST-LMS-"),"actual GPT practice receipt preserved in scheduled chat");}}
  out.putString("stream","PASS "+i.checks+" real group deadline checks\n");
 }catch(Throwable e){out.putString("stream","FAIL "+e+"\n");}
 i.sendStatus(1,out);try{Thread.sleep(100000);}catch(InterruptedException ignored){}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);
 }
}
